def max_sub_array(nums: list[int]) -> tuple[int, list[int]]:
    if not nums: return (0, [])
    best_sum = cur_sum = nums[0]
    start = best_start = best_end = 0
    for i in range(1, len(nums)):
        if cur_sum < 0:
            cur_sum = nums[i]
            start = i
        else:
            cur_sum += nums[i]
        if cur_sum > best_sum:
            best_sum = cur_sum
            best_start = start
            best_end = i
    return (best_sum, nums[best_start:best_end+1])
```

